import type { ApprovedDocumentEditionPayload } from './editionPolicy';

/**
 * Fail-closed build source: no approved editorial release manifest exists.
 * NEVER import GitHub research JSON into the web app to populate this map.
 * Future nonempty data must be generated by a separately reviewed release pipeline.
 */
const APPROVED_RELEASES: Readonly<Record<string, ApprovedDocumentEditionPayload>> = Object.freeze({});
export function getApprovedDocumentEdition(workId: string): ApprovedDocumentEditionPayload | null {
  return Object.prototype.hasOwnProperty.call(APPROVED_RELEASES, workId)
    ? APPROVED_RELEASES[workId] : null;
}
